import type { Readable } from 'node:stream';

/**
 * The seam between "evidence" as the product understands it and wherever the
 * bytes actually live.
 *
 * The contract is deliberately the intersection of a local directory and an
 * S3-style object store: opaque keys, streams in and out, `head` for
 * existence and size, `delete` that is idempotent. Nothing about directories,
 * buckets, ACLs or URLs leaks through it, so `AttachmentsService` compiles and
 * behaves identically whether the object landed on a disk or in a bucket.
 *
 * Keys are generated by the caller (`AttachmentsService.buildKey`) and are the
 * only thing a provider ever turns into a path. Providers must still refuse a
 * key that is not `safe` — see `isSafeStorageKey` — because a contract that
 * trusts its caller is one refactor away from path traversal.
 */
export interface StorageProvider {
  /** Machine name recorded on every attachment row: `local`, later `s3`. */
  readonly name: string;

  /**
   * Streams `body` under `key`, overwriting nothing: a key is used once. The
   * provider does not size-limit or validate the content; the caller inspects
   * the stream on its way through and deletes the object if it must.
   */
  put(key: string, body: Readable, options: { contentType: string }): Promise<void>;

  /** A readable stream of the object, or `null` when there is no such key. */
  get(key: string): Promise<Readable | null>;

  /** Existence and size without reading the body. */
  head(key: string): Promise<StoredObjectInfo | null>;

  /** Removes the object. A missing key is not an error: the goal is "gone". */
  delete(key: string): Promise<void>;
}

export interface StoredObjectInfo {
  sizeBytes: number;
}

export const STORAGE_PROVIDER = Symbol('StorageProvider');

/**
 * The key grammar every provider accepts: lower-case segments of
 * `[a-z0-9_-]` separated by single slashes, the last one carrying one
 * extension. `..`, empty segments, leading slashes, backslashes and anything
 * outside the alphabet fail, before any path is ever built from it.
 */
const SAFE_KEY = /^[a-z0-9_-]+(?:\/[a-z0-9_-]+)*\/[a-z0-9_-]+\.[a-z0-9]{1,8}$/;

export function isSafeStorageKey(key: string): boolean {
  return key.length <= 512 && SAFE_KEY.test(key);
}
